pub trait OrderPort { fn place(&self, order: &Order) -> Result<Receipt, Rejected>; }

pub(crate) struct LegacyAdapter { client: legacy::Client }   // vendor crate used here only

impl OrderPort for LegacyAdapter {
    fn place(&self, order: &Order) -> Result<Receipt, Rejected> {
        let dto = LegacyOrder::from(order);                      // From: infallible mapping
        let resp = self.client.submit(&dto).map_err(Rejected::from)?;
        Receipt::try_from(resp).map_err(Rejected::from)           // TryFrom: validated back
    }
}
